entries[126927] = { ["name"] = "Rezept: Zuckerglasiertes Fischfestmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein zuckerglasiertes Fischfestmahl zubereitet.\nBenötigt Klassische Kochkunst (150)\nVerkaufspreis:\nZuckerglasiertes Fischfestmahl\nBenutzen: Richtet für Eure Gruppe ein großartiges Festmahl her!\n\nStellt 10 Sek. lang pro Sekunde 10% Gesundheit und Mana wieder her und macht Euch satt, was die Vielseitigkeit 20 Min. lang erhöht. Kann nicht von Spielercharakteren über Stufe 50 genossen werden.\nVerkaufspreis:\nBenötigt Dunkelmond-Dolchmaul (5)" }
entries[126928] = { ["name"] = "Rezept: Zitronenkrautfilet", ["text"] = "Benutzen: Lehrt Euch, wie man ein Zitronenkrautfilet zubereitet.\nBenötigt Klassische Kochkunst (1)\nVerkaufspreis:\nZitronenkrautfilet\nBenutzen: Stellt 10 Sek. lang pro Sekunde 10% Eurer Gesundheit und Eures Manas wieder her und macht Euch satt, was die Vielseitigkeit 20 Min. lang erhöht. Ihr müsst beim Essen sitzen bleiben. Funktioniert nicht über Stufe 50.\nVerkaufspreis:\nBenötigt Dunkelmond-Dolchmaul (2)" }
entries[126929] = { ["name"] = "Rezept: Opulentes Dunkelmond-Festmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein opulentes Dunkelmond-Festmahl zubereitet.\nBenötigt Klassische Kochkunst (225)\nVerkaufspreis:\nOpulentes Dunkelmond-Festmahl\nBenutzen: Richtet für Eure Gruppe ein großartiges Festmahl her und hüllt sie in feinen Zwirn! Stellt 10 Sek. lang pro Sekunde 10% Gesundheit und Mana wieder her und macht Euch satt, was die Vielseitigkeit 20 Min. lang erhöht. Kann nicht von Spielercharakteren über Stufe 50 genossen werden.\nVerkaufspreis:\nBenötigt Dunkelmond-Dolchmaul (10)" }
