entries[127010] = { ["name"] = "Makellose Brustplatte der Lichtschmiede", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nBrust Platte\n34 Rüstung\n+10 [Stärke oder Intelligenz]\n+15 Ausdauer\nErhöht Eure Tempowertung um + 20.\n29 ( 29)\n\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 1126 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%.\n\nVerkäufer:\nEstelle Gendry\nZone:\nOrgrimmar - Tor von Orgrimmar\n\nVerkäufer:\nKrom Starkarm\nZone:\nEisenschmiede - Halle der Forscher" }
entries[127011] = { ["name"] = "Makellose Beinplatten der Lichtschmiede", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nBeine Platte\n30 Rüstung\n+10 [Stärke oder Intelligenz]\n+15 Ausdauer\nErhöht Eure kritische Trefferwertung um + 10.\nErhöht Eure Tempowertung um + 10.\n29 ( 29)\n\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 1126 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%.\n\nVerkäufer:\nGoram\nZone:\nOrgrimmar - Tal der Stärke\n\nVerkäufer:\nShay Pressler\nZone:\nSturmwind - Handelsdistrikt" }
