entries[127088] = { ["name"] = "Satinhandschuhe des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nHände Stoff\n2 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Priester\nBenötigt eine Horde-Rasse\nVereidigung des Gladiators (0/5)\nSatinrobe des Gladiators\nSatinkapuze des Gladiators\nSatinhandschuhe des Gladiators\nSatinmantelung des Gladiators\nSatingamaschen des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Disziplin: 'Sühne' erhöht jetzt die Bewegungsgeschwindigkeit eines von Euch geheilten verbündeten Ziels um 30% und verringert die Bewegungsgeschwindigkeit eines gegnerischen Ziels, dem Ihr Schaden zufügt, um 50%.\n(2) Set Heilig: Wenn 'Gebet der Besserung' ein Ziel heilt, erhaltet Ihr und das Ziel 10 Sek. lang 20 Vielseitigkeit. Bis zu 5-mal stapelbar.\n(2) Set Schatten: Wenn 'Dispersion' endet, erhaltet Ihr 10 Sek. lang 300 Vielseitigkeit.\n(4) Set Disziplin: Verringert die Abklingzeit von 'Schmerzunterdrückung' um 60 Sek.\n(4) Set Heilig: Verringert die Abklingzeit von 'Schutzgeist' um 60 Sek.\n(4) Set Schatten: Wenn Ihr 'Stille' einsetzt, erhaltet Ihr 30 Wahnsinn.\nVerkaufspreis:" }
entries[127089] = { ["name"] = "Lederhandschuhe des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nHände Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nKlassen: Schurke\nBenötigt eine Horde-Rasse\nGewänder des Gladiators (0/5)\nLedertunika des Gladiators\nLederhelm des Gladiators\nLederhandschuhe des Gladiators\nLederschiftung des Gladiators\nLederbeinschützer des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Meucheln: Einen Zauber mit einem Tritt erfolgreich zu unterbrechen erzeugt 3 Combopunkte. (2) Set Gesetzlosigkeit: Einen Zauber mit einem Tritt erfolgreich zu unterbrechen erzeugt 3 Combopunkte. (2) Set Täuschung: Einen Zauber mit einem Tritt erfolgreich zu unterbrechen erzeugt 3 Combopunkte.\n(4) Set Meucheln: Wenn Ihr 'Verschwinden' einsetzt, erhaltet Ihr 5 Combopunkte, und die kritische Trefferchance Eures nächsten Einsatzes von 'Verstümmeln' oder 'Vergiften' wird um 10% erhöht.\n(4) Set Gesetzlosigkeit: Wenn Ihr 'Verschwinden' einsetzt, erhaltet Ihr 5 Combopunkte, und die kritische Trefferchance Eures nächsten Einsatzes von 'Säbelhieb', 'Durchstoßen', 'Zwischen die Augen' oder 'Hinterhalt' wird um 100% erhöht.\n(4) Set Täuschung: 'Finte' erhöht außerdem 5 Sek. lang Eure Vielseitigkeit um 140 .\nVerkaufspreis:" }
entries[127090] = { ["name"] = "Ringpanzerstulpen des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nHände Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Schamane\nBenötigt eine Horde-Rasse\nKriegsrausch des Gladiators (0/5)\nRingpanzerrüstung des Gladiators\nRingpanzerhelm des Gladiators\nRingpanzerstulpen des Gladiators\nRingpanzerschiftung des Gladiators\nRingpanzergamaschen des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Elementar: Verringert die Abklingzeit von 'Verhexung' um 15 Sek.\n(2) Set Verstärkung: Wenn Ihr 'Wildgeist' aktiviert, wird die Dauer aller auf Euch gewirkten Kontrollverlusteffekte 30 Sek. lang um 25% verringert.\n(2) Set Wiederherstellung: Wenn Ihr einen schädlichen Magieeffekt oder einen Fluch von einem Verbündeten bannt, erhält dieser 10 Sek. lang 150 Vielseitigkeit.\n(4) Set Elementar: Nach dem Beschwören eines Elementars seid Ihr für 15 Sek. gegen Stille- und Unterbrechungseffekte immun.\n(4) Set Verstärkung: 'Windzorn' verursacht jetzt 2 weitere Male Schaden.\n(4) Set Wiederherstellung: Wenn das Ziel Eures Effekts 'Springflut' unter 50% Gesundheit fällt, wird die Dauer aufgefrischt.\nVerkaufspreis:" }
entries[127091] = { ["name"] = "Teufelsgewebte Handschützer des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nHände Stoff\n2 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Hexenmeister\nBenötigt eine Horde-Rasse\nTeufelsschleier des Gladiators (0/5)\nTeufelsgewebte Gewandung des Gladiators\nTeufelsgewebte Gugel des Gladiators\nTeufelsgewebte Handschützer des Gladiators\nTeufelsgewebte Amicia des Gladiators\nTeufelsgewebte Beinkleider des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gebrechen: Wenn Ihr betäubt, zum Schweigen gebracht, unterbrochen oder in Furcht versetzt werdet, wird ein Seelensplitter erzeugt. Kann nur einmal alle 15 Sek. auftreten. (15s Abklingzeit)\n(2) Set Dämonologie: Wenn Ihr oder Euer Begleiter über weniger als 20% der maximalen Gesundheit verfügt, erhaltet Ihr 200 Vielseitigkeit.\n(2) Set Zerstörung: Wenn Ihr betäubt, zum Schweigen gebracht, unterbrochen oder in Furcht versetzt werdet, wird ein Seelensplitter erzeugt. Kann nur ein Mal alle 15 Sek. auftreten. (15s Abklingzeit)\n(4) Set Gebrechen: Nach Einsatz von 'Dämonischer Zirkel: Teleport' erhaltet Ihr 10 Sek. lang 200 Vielseitigkeit. (15s Abklingzeit)\n(4) Set Dämonologie: Erhöht die von 'Seelenverbindung' hervorgerufene Heilung um 5%.\n(4) Set Zerstörung: Erhöht den Schaden von 'Verbrennen' an Zielen, die von 'Feuerbrand' betroffen sind, um 50%.\nVerkaufspreis:" }
entries[127092] = { ["name"] = "Plattenstulpen des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nHände Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nKlassen: Krieger\nBenötigt eine Horde-Rasse\nSchlachtrüstung des Gladiators (0/5)\nPlattenbrustharnisch des Gladiators\nPlattenhelm des Gladiators\nPlattenstulpen des Gladiators\nPlattenschultern des Gladiators\nPlattenbeinschützer des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Waffen: Wenn Ihr 'Sturmangriff' einsetzt, wird die kritische Trefferchance Eures nächsten Einsatzes von 'Tödlicher Stoß' um 50% erhöht.\n(2) Set Furor: Wenn Ihr 'Sturmangriff' einsetzt, wird die kritische Trefferchance Eures nächsten Einsatzes von 'Blutdurst' um 50% erhöht.\n(2) Set Schutz: Wenn Ihr 'Abfangen' einsetzt, wird die kritische Trefferchance Eures nächsten Einsatzes von 'Schildschlag' um 50% erhöht.\n(4) Set Waffen: Ihr erzeugt jetzt Wut, wenn Ihr Schaden erleidet. (4) Set Furor: Ihr erzeugt jetzt Wut, wenn Ihr Schaden erleidet. (4) Set Schutz: Ihr erzeugt jetzt Wut, wenn Ihr Schaden erleidet.\nVerkaufspreis:" }
entries[127093] = { ["name"] = "Schreckensplattenschultern des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nSchulter Platte\n12 Rüstung\n+3 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Todesritter\nBenötigt eine Horde-Rasse\nEntweihung des Gladiators (0/5)\nSchreckensplattenbrustharnisch des Gladiators\nSchreckensplattenhelm des Gladiators\nSchreckensplattenstulpen des Gladiators\nSchreckensplattenschultern des Gladiators\nSchreckensplattenbeinschützer des Gladiators\n(2) Set Blut: Der Einsatz von 'Todesgriff' erhöht den Schaden Eures nächsten Spezialangriffs mit einer Waffe um 25%. (2) Set Frost: Der Einsatz von 'Todesgriff' erhöht den Schaden Eures nächsten Spezialangriffs mit einer Waffe um 25%. (2) Set Unheilig: Der Einsatz von 'Todesgriff' erhöht den Schaden Eures nächsten Spezialangriffs mit einer Waffe um 25%.\n(4) Set Blut: 'Antimagische Hülle' wirkt sich zusätzlich auf den Verbündeten aus, der Euch am nächsten ist.\n(4) Set Frost: Wenn Euer 'Raureif' aktiv ist, erhöht Euer nächster Einsatz von 'Heulende Böe' den erlittenen Frostschaden aller Ziele für 8 Sek. um 10%.\n(4) Set Unheilig: Aktivierung von 'Dunkle Transformation' erhöht Euren verursachten Schattenschaden 15 Sek. lang um 20%.\nVerkaufspreis:" }
entries[127094] = { ["name"] = "Drachenlederschiftung des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nSchulter Leder\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nKlassen: Druide\nBenötigt eine Horde-Rasse\nSchutzgewandung des Gladiators (0/5)\nDrachenlederroben des Gladiators\nDrachenlederhelm des Gladiators\nDrachenlederhandschuhe des Gladiators\nDrachenlederschiftung des Gladiators\nDrachenlederbeinschützer des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gleichgewicht: Erhöht den Schadensbonus durch 'Lunarermächtigung' und 'Solarermächtigung' um 4%.\n(2) Set Wildheit: Wenn Ihr einen Zauber mit 'Schädelstoß' unterbrecht, wird die Abklingzeit von 'Tigerfuror' abgeschlossen.\n(2) Set Wächter: Wenn Ihr einen Spielercharakter mit 'Zerfleischen' trefft, während er einen Zauber wirkt oder kanalisiert, werden sein verursachter Schaden und seine hervorgerufene Heilung 3 Sek. lang um 35% verringert.\n(2) Set Wiederherstellung: Euer Zauber 'Eisenborke' gewährt dem Ziel zusätzlich 'Griff der Natur', wodurch die ersten 2 Angreifer 6 Sek. lang bewegungsunfähig gemacht werden.\n(4) Set Gleichgewicht: Wenn 'Sternensog' einen Spielercharakter trifft, wird die Zauberzeit von 'Lunarschlag' um 30% verringert und der Schaden von 'Solarzorn' um 30% erhöht. Hält 6 Sek. lang an.\n(4) Set Wildheit: Kritische Treffer von 'Schreddern' lassen das Ziel 6 Sek. lang um 10% erhöhten Schaden durch Eure Blutungseffekte erleiden.\n(4) Set Wächter: Während 'Überlebensinstinkte' aktiv ist, werden die 2 am nächsten stehenden Verbündeten um 35% des von Euch verursachten direkten Schadens geheilt.\n(4) Set Wiederherstellung: Erhöht den regelmäßigen Heilungseffekt von 'Blühendes Leben' um 15%.\nVerkaufspreis:" }
entries[127095] = { ["name"] = "Kettenschiftung des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nSchulter Kette\n8 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Jäger\nBenötigt eine Horde-Rasse\nJagdtracht des Gladiators (0/5)\nKettenrüstung des Gladiators\nKettenhelm des Gladiators\nKettenstulpen des Gladiators\nKettenschiftung des Gladiators\nKettengamaschen des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Tierherrschaft: Erhöht die Effektdauer von [ Zurechtstutzen : 'Zurechtstutzen' / 'Erschütternder Schuss'] um 2 Sek. (2) Set Treffsicherheit: Erhöht die Effektdauer von [ Zurechtstutzen : 'Zurechtstutzen' / 'Erschütternder Schuss'] um 2 Sek. (2) Set Überleben: Erhöht die Effektdauer von [ Zurechtstutzen : 'Zurechtstutzen' / 'Erschütternder Schuss'] um 2 Sek.\n(4) Set Tierherrschaft: Ihr und Euer Begleiter teilt Euch abnehmende Wirkungen von Kontrollverlusteffekten.\n(4) Set Treffsicherheit: 'Gezielter Schuss' verringert die Abklingzeit von 'Volltreffer' um 5 Sek.\n(4) Set Überleben: Wenn 'Aufschlitzen' Schaden verursacht, erhöht die Fähigkeit zusätzlich für 12 Sek. Euren gesamten dem Ziel zugefügten Schaden um 2%.\nVerkaufspreis:" }
entries[127096] = { ["name"] = "Seidene Amicia des Gladiators", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nSchulter Stoff\n3 Rüstung\n+3 Intelligenz\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Magier\nBenötigt eine Horde-Rasse\nOrnat des Gladiators (0/5)\nSeidene Robe des Gladiators\nSeidene Gugel des Gladiators\nSeidene Handschützer des Gladiators\nSeidene Amicia des Gladiators\nSeidene Beinkleider des Gladiators\nAltes Set: Bonus ist nicht aktiv\n(2) Set Arkan: Wenn Ihr erfolgreich einen Stärkungszauber raubt, wird ein Einsatz von 'Arkane Geschosse' ermöglicht.\n(2) Set Feuer: Der Einsatz von 'Versengen' verringert die Zauberzeit und erhöht die kritische Trefferchance von 'Feuerball' um 15%. Bis zu 3-mal stapelbar.\n(2) Set Frost: Beim Einsatz von 'Kältekegel' entsteht 6 Sek. lang am Boden des Zielbereichs eine Eisfläche, die Gegner um 50% verlangsamt.\n(4) Set Arkan: Während 'Arkane Macht' aktiv ist, könnt Ihr 'Arkanschlag' und 'Arkane Geschosse' aus der Bewegung heraus wirken.\n(4) Set Feuer: Wenn Ihr 'Kampfeshitze' aufzehrt, hat Euer Ziel von 'Pyroschlag' 10 Sek. lang eine um 15% erhöhte Chance, von 'Feuerball' kritisch getroffen zu werden.\n(4) Set Frost: 'Frostblitz' fügt verlangsamten Zielen 50% mehr Schaden zu.\nVerkaufspreis:" }
